"""ideas.py - the agent's quiet suggestions: generated by rules from its own state, each said once, never a card.

Upgrade 12 of the Grok Bot / Muse teardown (2026-11-08; Muse's Ideas feed, OpenMuse's rule-generated ideas with
content-hash ids). Sage had two ways to be proactive: a card (a decision the owner must take) or nothing. An idea is
neither: one plain line under the weekly digest ("your rules are near their cap", "the morning routine has failed
three mornings running"), surfaced once; if the owner wants it they say so in chat, if they ignore it it never
comes back. Zero LLM:

  generate()      every idea the rules find right now, each {id, text, source}; the id is a content hash so the
                  same idea has the same id whatever day it is found
  fresh()         the ones never surfaced (not in seen, not dismissed), at most MAX_PER_DIGEST
  mark(ideas)     record them as surfaced
  dismiss(id)     an owner's "drop that idea" (words in chat), never shown again
  render(ideas)   the digest's lines

Generators read: rules.json (cap), routines.json (last_error), capability.json (gaps open for days), the skill
radar's candidates.json (repeated un-skilled work), learnings/<lane>.md (lessons piling up), grants.json (a grant
about to expire). An organization adds its own in ideas_rules (profile.json -> ideas.extra, names only).
State: data/agent/ideas.json. Nothing here sends; digest.py says the lines.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import core  # noqa: E402

STATE = core.DATA / "ideas.json"           # {"seen": {id: ts}, "dismissed": [...], "external": {id: {text, source, key, ts}}}
EXTERNAL_KEEP_DAYS = 60
# the pack's lessons and the skill radar's candidates: a test scopes both (ASSISTANT_LEARNINGS / SKILL_RADAR_CANDIDATES)
LEARNINGS = Path(os.environ.get("ASSISTANT_LEARNINGS") or (core.VAULT / "assistant" / "learnings"))
RADAR = Path(os.environ.get("SKILL_RADAR_CANDIDATES") or (core.VAULT / "scripts" / "skill_radar" / "candidates.json"))
MAX_PER_DIGEST = 6
RULES_NEAR_CAP = 0.9
GAP_OPEN_DAYS = 7
LESSONS_PILE = 6
ROUTINE_FAILS = 3


def _id(text: str) -> str:
    return "i" + hashlib.sha256(re.sub(r"\s+", " ", text.strip().lower()).encode("utf-8")).hexdigest()[:10]


def _idea(text: str, source: str) -> dict:
    text = re.sub(r"\s+", " ", str(text or "")).strip()[:300]
    return {"id": _id(text), "text": text, "source": source}


def _state() -> dict:
    d = core.load(STATE, {})
    d.setdefault("seen", {})
    d.setdefault("dismissed", [])
    d.setdefault("external", {})
    return d


def suggest(text: str, source: str, key: str = "", say: str = "") -> dict:
    """Another module's proposal as an idea line instead of a card (2026-11-09: the YouTube scout's build ideas, the
    nightly review's asks and rule retirements, the money lane's price rises were four in five of a Monday digest's 96
    cards). `say` is the phrase an owner can reply with to act on it; `key` ties it to the proposer's own record.
    Said once under the next digest, never a card. -> the idea row."""
    i = _idea(str(text).strip() + (f" Say '{say}' and I'll do it." if say else ""), source)
    i["key"] = str(key or "")[:200]
    st = _state()
    if i["id"] in st["external"] or i["id"] in st["seen"] or i["id"] in st["dismissed"]:
        return {**st["external"].get(i["id"], i), "new": False}
    st["external"][i["id"]] = {**i, "ts": core.stamp()}
    cut = time.strftime("%Y-%m-%d %H:%M", time.localtime(time.time() - EXTERNAL_KEEP_DAYS * 86400))
    st["external"] = {k: v for k, v in st["external"].items() if str(v.get("ts") or "") >= cut}
    core.save(STATE, st)
    return {**i, "new": True}


def _g_external() -> list:
    st = _state()
    return [{"id": k, "text": v["text"], "source": v.get("source", "external")} for k, v in sorted(st["external"].items(), key=lambda kv: kv[1].get("ts", ""))]


# ------------------------------------------------------------------ generators
def _g_rules() -> list:
    n = len(core.rules_active())
    if n >= int(core.MAX_RULES * RULES_NEAR_CAP):
        return [_idea(f"You have {n} rules of a {core.MAX_RULES} cap. I can fold the near-duplicates into one each if you say so.", "rules")]
    return []


def _g_routines() -> list:
    out = []
    try:
        import routines
        for r in routines._load().get("routines") or []:
            if not r.get("active", True):
                continue
            hist = (core.load(routines.HISTORY, {}) or {}).get(r["id"]) or []
            fails = 0
            for h in reversed(hist):
                if h.get("ok"):
                    break
                fails += 1
            if fails >= ROUTINE_FAILS:
                out.append(_idea(f"The schedule '{r.get('title')}' has failed {fails} times running; I can test it or stop it.", "routines"))
    except Exception:  # noqa: BLE001
        pass
    return out


def _g_gaps() -> list:
    out = []
    try:
        d = core.load(core.DATA / "capability.json", {}) or {}
        now = time.time()
        for g in (d.get("gaps") or {}).values() if isinstance(d.get("gaps"), dict) else (d.get("gaps") or []):
            if not isinstance(g, dict) or g.get("status") in ("built", "dropped", "done", "closed"):
                continue
            try:
                ts = time.mktime(time.strptime(str(g.get("ts") or g.get("filed") or "")[:16], "%Y-%m-%d %H:%M"))
            except ValueError:
                continue
            if now - ts > GAP_OPEN_DAYS * 86400:
                out.append(_idea(f"A build request from {str(g.get('ts') or g.get('filed'))[:10]} is still open: {str(g.get('ask') or g.get('title') or '')[:120]}. Build it or drop it?", "capability"))
    except Exception:  # noqa: BLE001
        pass
    return out[:2]


def _g_radar() -> list:
    out = []
    try:
        d = core.load(RADAR, {}) or {}
        for c in (d.get("candidates") or [])[:2]:
            if isinstance(c, dict) and (c.get("title") or c.get("name")):
                out.append(_idea(f"The same kind of work keeps coming up without a skill: {str(c.get('title') or c.get('name'))[:100]}. I can write the skill.", "skill_radar"))
    except Exception:  # noqa: BLE001
        pass
    return out


def _g_lessons() -> list:
    out = []
    try:
        for p in sorted(LEARNINGS.glob("*.md")) if LEARNINGS.is_dir() else []:
            n = sum(1 for ln in p.read_text(encoding="utf-8", errors="replace").splitlines() if ln.startswith("- "))
            if n >= LESSONS_PILE:
                out.append(_idea(f"{n} lessons have piled up in the {p.stem} lane; the recurring ones could become rules.", "learnings"))
    except Exception:  # noqa: BLE001
        pass
    return out[:1]


def _g_grants() -> list:
    out = []
    try:
        sys.path.insert(0, str(core.VAULT / "assistant" / "scripts"))
        import policy
        now = time.time()
        for g in policy.active_grants(now):
            if g.get("until_ts") and 0 < float(g["until_ts"]) - now < 2 * 86400:
                out.append(_idea(f"Your standing yes for '{g.get('header')}' ends {g.get('until')}; say 'keep it' to extend it.", "grants"))
    except Exception:  # noqa: BLE001
        pass
    return out


GENERATORS = (_g_external, _g_rules, _g_routines, _g_gaps, _g_radar, _g_lessons, _g_grants)


def generate() -> list:
    out, seen = [], set()
    for g in GENERATORS:
        try:
            for i in g():
                if i["id"] not in seen:
                    seen.add(i["id"])
                    out.append(i)
        except Exception:  # noqa: BLE001
            continue
    return out


def fresh(limit: int = MAX_PER_DIGEST) -> list:
    st = _state()
    return [i for i in generate() if i["id"] not in st["seen"] and i["id"] not in st["dismissed"]][:limit]


def mark(ideas: list) -> None:
    st = _state()
    for i in ideas:
        st["seen"][i["id"]] = core.stamp()
    core.save(STATE, st)


def dismiss(iid: str, by: str = "") -> bool:
    st = _state()
    if iid in st["dismissed"]:
        return False
    st["dismissed"].append(iid)
    core.save(STATE, st)
    core.log_change("idea_dismiss", f"dropped idea {iid}", {"op": "none"}, by)
    return True


def render(ideas: list) -> str:
    if not ideas:
        return ""
    if len(ideas) == 1:
        return "One idea, no card: " + ideas[0]["text"]
    return "A few ideas, no cards (ignore any you don't want; none comes back):\n" + "\n".join(f"{n}. {i['text']}" for n, i in enumerate(ideas, 1))


if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8")
    a = sys.argv[1:]
    if a[:1] == ["dismiss"] and len(a) == 2:
        print("dropped" if dismiss(a[1], by="cli") else "already dropped")
    else:
        print(json.dumps(fresh() if a[:1] == ["fresh"] else generate(), indent=1, ensure_ascii=False))
